// Template families for charityevals' own models (built with the build-cea skill). Every family
// shares one skeleton: cost → reach → effect per unit → adjustments → outcome → your dollar's share,
// with canonical row ids, so two models of the same family can be compared row by row and every
// model ends in a unit with an exchange rate to the common unit. The skeleton JSON files live in
// .claude/skills/build-cea/templates/<family>.json (generated by its scripts/gen-templates.py); this
// file is what the checks enforce (src/engine/lint.ts), and src/engine/templates.test.ts runs every
// invariant and the lint on each skeleton filled in.
import type { z } from "zod";
import type { TemplateFamily } from "./schema";

export type Family = z.infer<typeof TemplateFamily>;
export type Basis = "past_average" | "marginal" | "unit_cost";

/** A shared figure a canonical row must read, itself or through the rows it is computed from:
 * `$assumption`, or `@fact` (a trailing `.` or `_` makes it a prefix). The site's one way for the
 * concept (docs/normalization.md 2.7-2.10). Missing: a high finding, unless marked medium. */
export type Read = { row: string; ref: string; why: string; severity?: "high" | "medium" };

export type TemplateSpec = {
  title: string;
  /** Output unit: a key of assumptions.units with a to_common formula. */
  unit: string;
  /** Row ids of the bottom line before and after the salary-sacrifice share (`donor`), and the
   * output: the donor row itself, or for animal families the species step's sum after it. */
  perDollar: string;
  donor: string;
  output: string;
  /** Section ids in the order the model must use them. */
  sections: string[];
  /** Rows every model of the family must have (canonical ids). */
  required: string[];
  /** Plausible bounds for canonical rows, checked on computed values. Outside: high-severity
   * finding, unless the explainer argues for it (then the auditor decides). */
  bounds: Record<string, [number, number]>;
  /** The estimate basis a model of this family usually has (INV-18, docs/normalization.md 2.10). */
  basis: Basis;
  /** Other bases the family's conventions name for a kind of dollar it often meets (templates.md
   * Convention 12): no low finding for them, but the reason still goes in the summary. */
  altBasis?: Basis[];
  reads: Read[];
};

/** The SAD version whose species weights are built into each shared per-change figure (each fact's
 * note): the ced_<species> row dividing it must name the same version (docs/normalization.md 2.4). */
export const SAD_FACT_VERSION: Record<string, string> = {
  "sad_factors.sads_per_hen_year_cage_to_aviary": "2024",
  "sad_factors.sads_per_meal_replaced": "2024",
  "sad_factors.sads_per_hen_year_enriched_to_aviary": "2025",
  "sad_factors.sads_per_broiler_bcc": "2025",
  "sad_factors.sads_per_shrimp_stunned": "2025",
};

/** Shared by every family. */
const SECTIONS = ["cost", "reach", "effect", "adjustments", "outcome", "donor"];
const COMMON_REQUIRED = [
  "program_spend",
  "overhead_ratio",
  "cost_total",
  "evidence_adj",
  "counterfactual_adj",
  "attribution_share_shared",
  "attribution_share",
  "total_adj",
  "outcome_total",
  "staff_cost_share",
  "salary_gap",
  "salary_sacrifice",
  "donor_cost_share",
];
const COMMON_BOUNDS: Record<string, [number, number]> = {
  overhead_ratio: [1, 2],
  evidence_adj: [0, 1.2],
  counterfactual_adj: [0, 1],
  attribution_share_shared: [0, 1],
  attribution_share: [0, 1],
  implementation_adj: [0, 1],
  leverage_funging_adj: [0.5, 1.5],
  unmodelled_benefits_adj: [-0.3, 0.6],
  staff_cost_share: [0, 1],
  salary_gap: [0, 0.8],
  donor_cost_share: [0, 1],
  persistence_years: [0, 50],
  years_of_impact: [0, 50],
  years_until_effect: [0, 15],
  years_until_avoided: [0, 60],
  marginal_vs_past_average: [0, 1],
};
/** Every family's staff-pay step: the gap is the site's judgment per kind of work. */
const STAFF_READS: Read[] = [
  { row: "salary_gap", ref: "@staff_pay.gap_", why: "the pay gap is a judgment the site makes once per kind of work (facts/staff_pay.json)", severity: "medium" },
];
/** A won pledge, law or rule counts the shared years, the wait until it takes effect discounted (2.9). */
const WON_REFORM: Read[] = [
  { row: "years_of_impact", ref: "$win_years_counted", why: "a won reform counts the site's one number of years ($win_years_counted, docs/normalization.md 2.9)" },
  { row: "discounted_years", ref: "$discount_rate", why: "the years counted and the wait before them are discounted at the shared rate" },
];

const donor = (unit: string) => [`${unit}_per_dollar`, `${unit}_per_donor_dollar`] as const;

function spec(title: string, unit: string, prefix: string, required: string[], bounds: Record<string, [number, number]>, basis: Basis, reads: Read[]): TemplateSpec {
  const [perDollar, output] = donor(prefix);
  return {
    title,
    unit,
    perDollar,
    donor: output,
    output,
    sections: SECTIONS,
    required: [...COMMON_REQUIRED, ...required, perDollar, output],
    bounds: { ...COMMON_BOUNDS, ...bounds },
    basis,
    reads: [...STAFF_READS, ...reads],
  };
}

/** Animal families count Ambitious Impact's SADs (the shared per-change figures) and end in
 * chicken-equivalent pain days through the species step (docs/normalization.md 2.4). */
function animal(title: string, required: string[], bounds: Record<string, [number, number]>, basis: Basis, reads: Read[]): TemplateSpec {
  const s = spec(title, "ced", "sads", required, bounds, basis, reads);
  return { ...s, output: "ced_per_donor_dollar", required: [...s.required, "ced_per_donor_dollar"] };
}

