/** A policy-research-meta model reports in its downstream unit: uov, wellby, ced (via SADs and the
 * species step, as the animal families) or tco2e (climate: the policy-research-meta-climate skeleton). */
export function allowedUnits(family: Family): string[] {
  return family === "policy-research-meta" ? ["uov", "wellby", "ced", "tco2e"] : [TEMPLATES[family].unit];
}

export function perDollarIds(family: Family, unit: string): { perDollar: string; donor: string; output: string } {
  if (family !== "policy-research-meta") {
    const t = TEMPLATES[family];
    return { perDollar: t.perDollar, donor: t.donor, output: t.output };
  }
  const prefix = unit === "ced" ? "sads" : unit === "wellby" ? "wellbys" : unit === "tco2e" ? "tco2e" : "uov";
  return { perDollar: `${prefix}_per_dollar`, donor: `${prefix}_per_donor_dollar`, output: unit === "ced" ? "ced_per_donor_dollar" : `${prefix}_per_donor_dollar` };
}

/** Rows a tco2e model needs beyond its family's (docs/normalization.md 2.5). */
export const CLIMATE_REQUIRED = ["years_until_avoided", "air_pollution_weight", "extra_deaths_per_tco2e"];
